/**
 * SLATE — an account's life at each bank: what a term deposit does at its
 * end and costs to break, what savings charges past its free withdrawals,
 * whether the bank rounds purchases up into savings, when an idle account
 * goes dormant; and, by country, when unclaimed money goes to the state and
 * how long a new account or card may be canceled.
 *
 * From research that read each bank's own terms (`probe/more/savings.jsonl`)
 * and each country's law or scheme (`probe/more/unclaimed.jsonl`).
 * Generated by `probe/gen-accountlife.cjs`. Amounts in the bank's
 * currency's hundredths.
 */

import type { Money } from '../core/money';

export type TermEnd = 'renews' | 'savings' | 'paid_out';

export interface BankAccountLife {
  /** Whether a term deposit can be broken before its end. */
  early?: boolean;
  /** The penalty in days of interest, by the term's length: under so many months, so many days. */
  penaltyDays?: readonly { underMonths?: number; days: number }[];
  /** The bank's own words for its penalty, where it isn't days of interest. */
  penaltyWords?: string;
  /** The penalty is never more than the interest the term has earned; and in a term's first week it's at least so many days' interest, cap or none. */
  penaltyCapped?: boolean;
  penaltyFirstWeekDays?: number;
  /**
   * What a term deposit does at its end if its holder says nothing: renews
   * for the same term, moves into the bank's easy-access savings, or is paid
   * out; what else they may choose; and how many days before the end a
   * change must be made. Read by hand from the bank's words, which are kept.
   */
  atEnd?: TermEnd;
  endChoices?: readonly TermEnd[];
  endNoticeDays?: number;
  maturityWords?: string;
  /** Days after it renews to change it or take the money without penalty. */
  graceDays?: number;
  /** Whether interest can be taken during the term. */
  interestDuringTerm?: boolean;
  /** Savings: withdrawals free a month, and the fee for each after. */
  freeWithdrawals?: number;
  withdrawalFee?: Money;
  /** Round-ups into savings, in the bank's words, where it offers them. */
  roundUp?: string;
  /** An idle account: months to inactive and to dormant, and what that does. */
  inactiveMonths?: number;
  dormantMonths?: number;
  dormancyWords?: string;
  /** A dormant account earns nothing, where the bank's words say so. */
  stopsInterest?: boolean;
  source: string;
}

export interface CountryUnclaimed {
  /** Years untouched before the money goes to the state or a scheme. */
  years?: number;
  to?: string;
  claimBack?: string;
  /** Days a new account or card opened at a distance may be canceled. */
  coolingOffDays?: number;
  source: string;
}

/** By bank id. */
export const ACCOUNT_LIFE: Readonly<Record<string, BankAccountLife>> = JSON.parse("{\"us-chase\":{\"source\":\"https://www.chase.com/content/dam/chase-ux/documents/personal/checking/deposit-account-agreement.pdf, 2026-09-26\",\"early\":true,\"penaltyDays\":[{\"underMonths\":6,\"days\":90},{\"underMonths\":24,\"days\":180},{\"days\":365}],\"penaltyWords\":\"Personal CDs: term under 6 months, 90 days' interest on the amount withdrawn; 6 to under 24 months, 180 days' interest; 24 months or more, 365 days' interest; in each case capped at the total interest earned in the current term. Withdrawal less than 7 days after opening or after another principal withdrawal: at least 7 days' interest. Penalty deducted from principal.\",\"penaltyCapped\":true,\"penaltyFirstWeekDays\":7,\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"automatically renewable CDs renew on the maturity date for the same term at the CD standard rate (or relationship rate); single-maturity CDs do not renew and stop earning interest on the maturity date\",\"graceDays\":10,\"interestDuringTerm\":true,\"inactiveMonths\":24,\"dormantMonths\":30,\"dormancyWords\":\"Checking/savings with no customer-initiated activity for 24 months may become inactive (a CD counts as inactive from funding until maturity or a customer early withdrawal). After 30 months the account may be dormant: no debit card purchases, no transfers, deposits or withdrawals, no digital banking access; debit card restricted. After a longer state-law period it may be closed and escheated to the state as unclaimed property, with a letter sent in advance.\"},\"us-bank-of-america\":{\"source\":\"https://www.bankofamerica.com/salesservices/deposits/resources/deposit-agreements/, 2026-09-26\",\"early\":true,\"penaltyDays\":[{\"underMonths\":3,\"days\":7},{\"underMonths\":12,\"days\":90},{\"underMonths\":60,\"days\":180},{\"days\":365}],\"penaltyWords\":\"On the principal withdrawn, at the account's rate: terms under 90 days, the greater of all interest earned on the amount withdrawn or 7 days' interest; 90 days up to 12 months, 90 days' interest; 12 months up to 60 months, 180 days' interest; 60 months or longer, 365 days' interest. Any cash bonus paid at opening or renewal is added to the penalty. Taken from interest first, then from principal. The fee schedule adds a 7-day-interest penalty for withdrawals in the first 6 days of a term.\",\"penaltyFirstWeekDays\":7,\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically on the maturity date, principal and interest reinvested at the rate then offered, unless the customer says otherwise before the grace period ends; non-renewing CDs stop earning interest at maturity\",\"graceDays\":7,\"interestDuringTerm\":true,\"roundUp\":\"Keep the Change: each Bank of America debit card purchase by an owner of the enrolled checking account is rounded up to the next whole dollar. The round-ups posted each business day are added up and moved to the enrolled savings account in one transfer at the end of that business day. No transfer happens on a day when available funds are short or the checking account is overdrawn. The transfer stays in savings even if the purchase is later reversed.\",\"dormancyWords\":\"The abandonment period is set by state law, generally the state on the statement address, and bank charges, interest and automatic deposits or withdrawals usually do not count as activity. Before escheat the bank may put the account in inactive status and then charge regular monthly maintenance and other fees, stop sending statements, stop paying interest, and refuse to pay items. After the funds are turned over, the customer must claim them from the state.\",\"stopsInterest\":true},\"us-wells-fargo\":{\"source\":\"https://www.wellsfargo.com/assets/pdf/small-business/agreement.pdf, 2026-09-26\",\"early\":true,\"penaltyDays\":[{\"underMonths\":3,\"days\":30},{\"underMonths\":13,\"days\":91},{\"underMonths\":25,\"days\":182},{\"days\":365}],\"penaltyWords\":\"Fixed Rate CDs, by term: under 90 days (under 3 months), 1 month's interest; 90 through 365 days (3-12 months), 3 months' interest; over 12 through 24 months, 6 months' interest; over 24 months, 12 months' interest. One month's interest = rate x principal withdrawn / 12, taken from earned interest and then from principal. Regulation D penalty of 7 days' simple interest for withdrawals within 7 days of opening or of a prior penalized withdrawal.\",\"penaltyFirstWeekDays\":7,\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically at maturity, typically for the same term at the standard rate on the maturity date, unless funds are withdrawn\",\"graceDays\":10,\"interestDuringTerm\":true,\"roundUp\":\"Not a round-up. Way2Save 'Save As You Go' moves a flat $1 from the linked Wells Fargo checking account to Way2Save Savings for each one-time debit card purchase or online Bill Pay payment that posts. The day's count x $1 goes over as one transfer the next business day, and nothing moves if checking lacks available funds, is overdrawn, or Overdraft Protection was used.\",\"dormantMonths\":34,\"dormancyWords\":\"Generally dormant after no customer-initiated activity (branch or ATM deposit or withdrawal, or a check) for 12 months for checking, 34 months for savings, and 34 months after first renewal for CDs. Automatic transfers and direct deposits do not count unless state law says so. Safeguards may restrict ATM/debit transfers between Wells Fargo accounts, phone transfers, online, mobile and text banking transfers and Bill Pay, and wires. A dormant account linked to Prime or Premier Checking may be delinked and lose its benefits. If there is no contact within the state unclaimed-property period (generally 3 or 5 years), the bank closes the account and sends the funds to the state (escheat), and statements stop.\"},\"us-citi\":{\"source\":\"https://online.citi.com/JRS/popups/ao/CDAA.pdf, 2026-09-26\",\"early\":true,\"penaltyDays\":[{\"underMonths\":13,\"days\":90},{\"days\":180}],\"penaltyWords\":\"On the principal withdrawn: 90 days' simple interest for CD terms of 1 year or less; 180 days' simple interest for terms over 1 year. May be taken partly or wholly from principal. Waived on the owner's death or legal incompetence. The No Penalty CD (12-month) allows withdrawal of the full balance and interest with no penalty after the first 6 days, but no partial withdrawals.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically at maturity for the same term at the rate in effect on the maturity date, unless the term is changed or no longer offered\",\"graceDays\":7,\"interestDuringTerm\":true,\"roundUp\":\"Spend & Save: each purchase with an enrolled Citi credit or debit card is rounded up to the nearest whole dollar (a $5.25 purchase adds $0.75) into a running tally, without raising the charge. The tally, up to $15 per transfer with any excess carried into the next one, moves from a designated Citi checking account to a designated Citi savings account daily or weekly, as chosen. No transfer happens while checking is below a customer-set minimum (transfers won't happen under $50).\",\"dormancyWords\":\"Dormancy periods follow the state abandoned-property law of the last known address (South Dakota law if the address is outside the US). Balances with no customer-initiated activity may be sent to the state. CD auto-renewals do not count as activity, and the state period can start after the first maturity. Citi may also restrict an account it finds inactive.\"},\"us-capital-one\":{\"source\":\"https://www.capitalone.com/bank/disclosures/cds/online-cds/, 2026-09-26\",\"early\":true,\"penaltyDays\":[{\"underMonths\":13,\"days\":91},{\"days\":182}],\"penaltyWords\":\"360 CD: 3 months' interest for terms of 12 months or shorter; 6 months' interest for terms over 12 months, regardless of when redeemed. Waived on an owner's death or legal incompetence. No partial withdrawals of principal during the term; only the whole CD can be redeemed early.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically into a CD of the same term (or the nearest available term) at the rate offered on the maturity date\",\"graceDays\":10,\"interestDuringTerm\":true,\"dormantMonths\":24,\"dormancyWords\":\"Dormant after 24 months with no transactional activity. Paper statements may stop, but accounts can still be viewed online. Once an account is presumed abandoned under state law, it stops earning interest. After the state's period, all the customer's deposit accounts are closed and the money goes to the state (escheat), where it can be claimed.\",\"stopsInterest\":true},\"ca-rbc\":{\"source\":\"https://www.rbcroyalbank.com/onlinebanking/servicech/pdf/PDA_Account_Disclosure_Booklet.pdf, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Non-redeemable GIC: no early access, cannot be cashed before maturity. Redeemable (one-year cashable) GIC: fully or partially cashable at any time; no interest if cashed in the first 29 days; after 30+ days interest is paid at a reduced early-redemption rate, calculated daily.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically (same term and type at RBC's then-current rate for comparable deposits; registered-plan GICs renew for a one-year term) unless instructed otherwise\",\"graceDays\":10,\"interestDuringTerm\":true,\"freeWithdrawals\":1,\"withdrawalFee\":200,\"inactiveMonths\":12,\"dormantMonths\":24,\"dormancyWords\":\"Account becomes inactive after 12 months with no transactions; written notices after 2, 5 and 9 years; Inactive (dormant) Account fee charged for years 2 to 8 ($20) and year 9 ($40), or the balance if less; an inactive account that reaches $0.00 is closed without notice; at 10 years the account is closed and the balance sent to the Bank of Canada.\"},\"ca-td\":{\"source\":\"https://www.td.com/content/dam/tdct/document/pdf/accounts/802228-non-registered-without-coversheet.pdf, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Non-redeemable GIC 'cannot be redeemed before its maturity date'. Redeemable/cashable GICs may be redeemed per the Confirmation: TD 1-Year Cashable GIC can be cashed after 30 days in full or in part without penalty; TD 3-Year Premium Cashable GIC cashable any time at tiered pre-encashment (reduced) rates.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"per chosen maturity instruction: pay out by check or credit to an account, or renew automatically (cashable GICs auto-renew principal and interest into a TD 1-Year Cashable GIC); no interest is paid beyond the maturity date\",\"interestDuringTerm\":true,\"freeWithdrawals\":1,\"withdrawalFee\":300,\"roundUp\":\"Simply Save: not a true round-up; moves a fixed amount you choose ($0.50 to $5.00) from chequing to a TD savings account each time you make a TD Access Card debit purchase and/or ATM withdrawal, transferred daily, weekly or biweekly; skipped if chequing lacks funds; no fee.\",\"dormantMonths\":12,\"dormancyWords\":\"Chequing and savings accounts inactive for 1 year become 'dormant'; notices are sent after the 2nd, 5th and 9th year with reactivation options; accounts dormant 10 years are transferred to the Bank of Canada (USD and other foreign-currency accounts too since Nov 2024). Reactivate via EasyLine or a branch.\"},\"ca-scotiabank\":{\"source\":\"https://www.scotiabank.com/content/dam/scotiabank/canada/en/documents/Scotiabank_Non-Registered_TFSA_RESP_and_RDSP_Guaranteed_Investment_Certificates_terms.pdf, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Non-Redeemable GICs are not redeemable before maturity except on the owner's death (then all interest earned to date is paid). Cashable GICs fully redeemable any time (min withdrawal $500, min remaining $500); no interest if redeemed within 30 days of issue. Redeemable GICs: early redemptions earn a reduced 'early redemption interest rate' (available on request); no interest if redeemed within 30 days.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically if the GIC has an automatic renewal provision (same term, rate prevailing on the renewal date); otherwise per renewal instructions given up to maturity\",\"graceDays\":10,\"interestDuringTerm\":true,\"freeWithdrawals\":0,\"withdrawalFee\":500,\"roundUp\":\"Bank The Rest: every Scotia debit card purchase is rounded up to the next multiple of $1 or $5 (chosen at enrolment); the round-up amounts are added together at the end of the day and transferred to a Money Master Savings Account; free.\",\"dormantMonths\":24,\"dormancyWords\":\"Inactive-account fees charged with each annual notice of inactivity: after 2, 3 and 4 years $20.00; after 5 to 8 years $30.00; at the nine-year notice of transfer to the Bank of Canada $40.00. Reactivation requires a branch visit with ID and proof of address.\"},\"ca-bmo\":{\"source\":\"https://www.bmo.com/pdf/Agreements_Bank_Plans_and_Fees_for_Everyday_Banking.pdf, 2026-09-26\",\"early\":false,\"penaltyWords\":\"BMO GIC (non-cashable): 'The Investment is not redeemable before the Maturity Date.' Cashable GICs (e.g. Variable Rate GIC): fully or partially cashable any time, no interest if redeemed within 30 days of issue; Cashable RateRiser GIC cashable in full at any time.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"endNoticeDays\":21,\"maturityWords\":\"registered accounts reinvest automatically into a BMO GIC of the same term and interest option at the then-current rate; non-registered follow the instructions given at purchase (auto-reinvested only if reinvestment instructions were given); instructions can be changed only in writing within 21 days before maturity\",\"interestDuringTerm\":true,\"freeWithdrawals\":0,\"withdrawalFee\":500,\"inactiveMonths\":12,\"dormantMonths\":24,\"dormancyWords\":\"Accounts with a $0 balance and no customer activity for at least a year are closed. No customer activity for 2+ years = Dormant; notices mailed after 2 and 5 years; if not acknowledged within 60 days a Dormant Account Fee is charged ($20 at 2 years, $30 at 5 years); the account is closed without notice if funds can't cover the fee; after 9 years it is closed with a final notice; the unclaimed balance goes to the Bank of Canada in year 10 with a $40 fee.\"},\"ca-cibc\":{\"source\":\"https://www.cibc.com/content/dam/personal_banking/bank_accounts/pdfs/cibc-pasf-en.pdf, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Non-redeemable GIC: access 'only at maturity'. Redeemable GIC: full interest paid to the redemption date if withdrawn 30+ days after issue; no interest if withdrawn within the first 29 days (CIBC's rate page also says redeemable GICs cash out 'at specified early redemption rates').\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically into the same product and term unless changed with an advisor before maturity\",\"freeWithdrawals\":0,\"withdrawalFee\":500,\"dormantMonths\":24,\"dormancyWords\":\"Account is dormant after 24 months with no customer-initiated transactions; monthly statements switch to quarterly; annual fee $20 (dormant 2 to 4 years), $30 (5 to 8 years), $40 (9 years), or the balance if less (not charged where all holders are 18 or younger); after 10 years the CAD balance goes to the Bank of Canada.\"},\"mx-bbva\":{\"source\":\"https://www.bbva.mx/personas/productos/inversion/inversion-a-plazo/pagare.html, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Pagaré (PRLV): early withdrawal not permitted; funds stay invested until the term ends ('Durante el plazo que esté invertido tu dinero, no lo podrás retirar, hasta que venza dicho plazo'); BBVA cites the Ley de Instituciones de Crédito as restricting early cancelation.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"at maturity you choose to withdraw or reinvest the principal alone or principal plus returns; automatic renewal available (renew with gains, renew without gains, or do not renew)\",\"roundUp\":\"BBVA Plan (app): the 'Redondeo' rule rounds each purchase made with linked cards up to $10, $50 or $100 (your choice) and sends the difference to your savings goal (e.g. rounding to $100 on a $90 purchase takes $10); for credit cards the money comes from the domiciled or favorite account. Other rules: 5/10/15/20% of each purchase, voluntary deposits; no fees; withdraw any time.\",\"dormantMonths\":36,\"dormancyWords\":\"After 3 years with no deposits or withdrawals the balance is moved to the bank's 'cuenta global' (the bank must notify the registered address 90 days before the 3 years are up; the money stays yours, is charged no fees and earns monthly interest; fee charges do not count as movement). After 3 more years in the cuenta global with no claim or movement (6 years in all), balances not exceeding 300 days' minimum wage (Mexico City) go to the Beneficencia Pública (Ley de Instituciones de Crédito art. 61).\"},\"mx-santander\":{\"source\":\"https://web.archive.org/web/20260517151339/https://www.santander.com.mx/personas/inversiones/inversion-digital.html, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Pagaré / inversión a plazo: capital and interest are available at maturity; Mexican bank pagarés with yield payable at maturity cannot normally be redeemed early (as BBVA and Banamex state). A third-party guide claims Santander 'podría aplicar una penalización o ajuste en los intereses' on early withdrawal; unverified.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"instruction chosen at contracting ('instrucción al vencimiento'): renew capital and interest, renew capital and pay interest to the check account, or pay both out; a third-party guide says it renews automatically at the prevailing rate unless told otherwise\",\"dormantMonths\":36,\"dormancyWords\":\"After 3 years with no deposits or withdrawals the balance is moved to the bank's 'cuenta global' (the bank must notify the registered address 90 days before the 3 years are up; the money stays yours, is charged no fees and earns monthly interest; fee charges do not count as movement). After 3 more years in the cuenta global with no claim or movement (6 years in all), balances not exceeding 300 days' minimum wage (Mexico City) go to the Beneficencia Pública (Ley de Instituciones de Crédito art. 61).\"},\"mx-banamex\":{\"source\":\"https://www.banamex.com/es/centro-de-ayuda/cuentas/ahorro-facil/pagare_banamex.htm, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Pagaré Banamex: cannot be withdrawn before maturity; 'la regulación aplicable no permite la cancelación anticipada'.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"per the choice made when opening: reinvest principal plus returns automatically into a new term, or have money and returns reimbursed\",\"dormantMonths\":36,\"dormancyWords\":\"After 3 years with no deposits or withdrawals the balance is moved to the bank's 'cuenta global' (the bank must notify the registered address 90 days before the 3 years are up; the money stays yours, is charged no fees and earns monthly interest; fee charges do not count as movement). After 3 more years in the cuenta global with no claim or movement (6 years in all), balances not exceeding 300 days' minimum wage (Mexico City) go to the Beneficencia Pública (Ley de Instituciones de Crédito art. 61).\"},\"mx-banorte\":{\"source\":\"https://web.archive.org/web/20260410151848/https://www.banorte.com/Personal/Ahorro-e-Inversion/Inversiones-a-Plazo/Pagare-Digital.html, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Pagaré Digital: capital and interest are liquid at maturity (no early withdrawal offered). The alternative Inversión Plus (a deposit withdrawable on preset days) allows early withdrawal of up to 100% for a commission: 0.3% on 7/14/28-day terms, 0.5% on 91-day, 1% on 182/364-day.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"maturity instruction chosen at contracting (renew, or pay to the cuenta eje); rate fixed for the term, reset weekly off Cetes for new placements\",\"dormantMonths\":36,\"dormancyWords\":\"After 3 years with no deposits or withdrawals the balance is moved to the bank's 'cuenta global' (the bank must notify the registered address 90 days before the 3 years are up; the money stays yours, is charged no fees and earns monthly interest; fee charges do not count as movement). After 3 more years in the cuenta global with no claim or movement (6 years in all), balances not exceeding 300 days' minimum wage (Mexico City) go to the Beneficencia Pública (Ley de Instituciones de Crédito art. 61).\"},\"gb-barclays\":{\"source\":\"https://www.barclays.co.uk/content/dam/documents/personal/savings/savingsbondterms.pdf, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Fixed Rate Savings Bond: no withdrawals and no early closure unless the bond's own information says otherwise (then 'there may be a fee'); exceptions only in exceptional circumstances (illness, relationship ending, financial difficulty) or death/bankruptcy.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"savings\",\"paid_out\"],\"maturityWords\":\"Barclays writes at least three weeks before maturity offering a new bond (same or shorter term, same interest frequency) or an instant access savings account; if you do nothing the offer is accepted and money moves on the first working day after maturity; to take the money you must tell them before the maturity date and it is paid to your Barclays account the next working day\",\"interestDuringTerm\":true,\"dormantMonths\":180,\"dormancyWords\":\"Unused accounts may be closed after Barclays tries to contact you (closed within 90 days of first contact if no reply); remaining money goes to a central holding account and keeps earning the same interest; after 15+ years of inactivity balances may go to Reclaim Fund Ltd, still reclaimable.\"},\"gb-lloyds\":{\"source\":\"https://www.lloydsbank.com/savings/online-fixed-bonds.html (read via web.archive.org 2026 snapshot; live site returned an error page), 2026-09-26\",\"early\":true,\"penaltyDays\":[{\"underMonths\":12,\"days\":90},{\"underMonths\":24,\"days\":180}],\"penaltyWords\":\"Online Fixed Bond: no withdrawals; can close early only in a branch with a counter; charge equal to 90 days' gross interest on the 1-year bond, 180 days' gross interest on the 2-year bond; you may get back less than you put in.\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\",\"paid_out\"],\"maturityWords\":\"at the end of the 1 or 2 year term the account changes to a Standard Saver (easy access, variable) unless you choose another option; Lloyds contacts you beforehand\",\"interestDuringTerm\":true,\"roundUp\":\"Save the Change: debit card spending is rounded up to the nearest pound and the change is transferred to your nominated Lloyds savings account at the start of the next working day, provided it doesn't take the current account overdrawn; joint accounts save change from all holders' cards\",\"dormantMonths\":180,\"dormancyWords\":\"Balances in accounts inactive or dormant 15 years or more may be transferred to Reclaim Fund Ltd under the unclaimed assets scheme; customers keep the right to reclaim.\"},\"gb-natwest\":{\"source\":\"https://www.natwest.com/savings/fixed-term-savings-account.html, 2026-09-26\",\"early\":true,\"penaltyDays\":[{\"days\":90}],\"penaltyWords\":\"Fixed Term Savings Account: no withdrawals during the term; early closure needs 35 days' notice and carries a charge equal to the lower of interest earned or 90 days' interest; you never get back less than your deposit.\",\"penaltyCapped\":true,\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"savings\"],\"endNoticeDays\":5,\"maturityWords\":\"reinvests automatically into a new fixed term unless you opt out (opt-out form at least 5 days before maturity); if you opt out it converts to a Primary Saver on the maturity date\",\"interestDuringTerm\":true,\"roundUp\":\"Round Ups: debit card and contactless payments are rounded up to the nearest pound and the spare change goes to an eligible instant access savings account (not Instant Access ISA or Limited Edition Saver); optional multiplier 2x-5x; never takes you into overdraft; needs the mobile app\",\"inactiveMonths\":60,\"dormantMonths\":69,\"dormancyWords\":\"An account unused for 5 years or more is classed dormant; NatWest sends a notice giving 9 months to use it, after which (5 years 9 months) it is closed; funds can still be reclaimed.\"},\"gb-hsbc\":{\"source\":\"https://www.hsbc.co.uk/savings/products/fixed-rate/, 2026-09-26\",\"early\":true,\"penaltyDays\":[{\"days\":90}],\"penaltyWords\":\"Fixed Rate Saver: may close the whole account early (no partial withdrawals) for a fee equal to the lower of interest earned or a maximum of 90 days' interest.\",\"penaltyCapped\":true,\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"account closes and funds plus interest are paid to the HSBC account they came from, unless you arranged reinvestment\",\"graceDays\":90,\"interestDuringTerm\":true,\"inactiveMonths\":24,\"dormantMonths\":180,\"dormancyWords\":\"Accounts unused for typically 2 years are inactive/dormant: HSBC freezes inactive accounts in credit, closes zero-balance ones, and may close accounts of GBP 10 or less donating the balance to charity (reclaimable); after 15+ years balances may go to Reclaim Fund Ltd.\"},\"gb-santander\":{\"source\":\"https://www.santander.co.uk/assets/s3fs-public/AD_documents/fixed_rate_bonds_save0009oct23hcd_lr.pdf, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Fixed Rate Bond: you can't take money out during the term and can't cancel once opened; in exceptional circumstances (e.g. death of an account holder) Santander may allow early closure.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"endNoticeDays\":30,\"maturityWords\":\"choose what to do up to one month before the term ends; if Santander doesn't hear from you the account transfers to a Fixed Rate Reward Bond\",\"interestDuringTerm\":true,\"inactiveMonths\":36,\"dormantMonths\":180,\"dormancyWords\":\"No transactions for 1 year (banking accounts) or 3 years (savings accounts) and Santander may treat the account as dormant: no transactions, statements, letters or cards until reactivated, but it keeps earning interest; after 15 years balances may go to Reclaim Fund Ltd.\"},\"gb-nationwide\":{\"source\":\"https://www.nationwide.co.uk/savings/fixed-rate-online-bond, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Fixed Rate Online Bond: 14-day cancelation period after opening; after that no access at all until maturity, and no option to withdraw early by paying an interest penalty.\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\",\"paid_out\"],\"maturityWords\":\"matures into an instant access maturity account (lower variable rate, withdraw any time); instructions can be given up to 30 days before maturity; you can reinvest, transfer or withdraw without penalty afterwards\",\"interestDuringTerm\":true,\"dormantMonths\":180,\"dormancyWords\":\"After 15 consecutive years with no contact or transactions Nationwide closes the account and transfers the money to Reclaim Fund Ltd; a letter is sent at 14 years 10 months; money is always reclaimable, with interest that would have been earned.\"},\"ie-aib\":{\"source\":\"https://www.aib.ie/our-products/savings-and-deposits/personal-fixed-term-deposit-account, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Personal Fixed Term Deposit: cannot be closed before maturity; 'Percentage Access' lets you withdraw up to 25% once per fixed term, keeping at least EUR 5,000 in the account; within 14 days of opening you can end the agreement free but earn no interest.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"endNoticeDays\":1,\"maturityWords\":\"reinvests automatically into the same or similar term at the prevailing rate unless you instruct otherwise (instruction changeable in the app until 18:00 the business day before maturity)\",\"interestDuringTerm\":true,\"dormantMonths\":180,\"dormancyWords\":\"Irish Dormant Accounts Act 2001: no activity for 15 years makes an account dormant; the holder can reactivate by a transaction until 31 March, after which funds go to the Dormant Accounts Fund (NTMA); the money plus interest stays reclaimable.\"},\"ie-bank-of-ireland\":{\"source\":\"https://personalbanking.bankofireland.com/save-and-invest/savings/fixed-term-savings-accounts/advantage-deposit-account/features-and-benefits/, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Advantage Fixed Term Deposit: you cannot close or terminate the account before the end of the term; up to 25% may be withdrawn during the term.\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\",\"paid_out\"],\"maturityWords\":\"if no instructions, the full balance is re-deposited into the Variable Rate Call account (0.10% AER variable); BOI contacts you before the end of the term\",\"graceDays\":30,\"dormantMonths\":180,\"dormancyWords\":\"Irish Dormant Accounts Act 2001: 15 years with no activity makes an account dormant; reactivation possible until 31 March, then funds go to the Dormant Accounts Fund; always reclaimable with interest.\"},\"ie-ptsb\":{\"source\":\"https://www.ptsb.ie/saving-and-investing/deposit-accounts/fixed-term-deposit-account/ (via web.archive.org; live site 403) and PTSB T&C PDF https://www.ptsb.ie/globalassets/pdf-documents/terms-and-conditions/current-account-including-online-explore-account-savings--investments/, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Fixed Term Deposit: free withdrawal within 14 days of opening; after that an early withdrawal closes the account and a charge applies, the greater of 1% x A x T/365 or A x T x D%/365 (A = amount withdrawn, T = days of term left, D = market rate difference), minimum EUR 20; for Interest First accounts interest already paid for the unexpired term is also reclaimed.\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\",\"paid_out\"],\"maturityWords\":\"branch fixed deposits roll over into an Instant Access Account (0.01% variable) unless you instruct otherwise; online fixed deposits renew for a similar term at the rate then applying\",\"graceDays\":14,\"inactiveMonths\":36,\"dormantMonths\":180,\"dormancyWords\":\"No transactions for 3 continuous years makes an account 'Inactive' (PTSB may require identity and address verification before operating it); after 15 years with no customer transaction it is designated dormant and, if not reactivated by the next 31 March, funds go to the NTMA, remaining reclaimable.\"},\"is-landsbankinn\":{\"source\":\"https://www.landsbankinn.is/Uploads/documents/UmLandsbankann/Skilmalar/1515_Fastvaxtareikningur.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Fastvaxtareikningur (3, 6, 12 or 24 months): deposit and interest are bound; closing before the binding ends is allowed but an úttektargjald applies: 2% of the amount withdrawn.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\"],\"maturityWords\":\"at the end of the binding the account is closed and the balance plus interest (less capital income tax) is paid to the same Landsbankinn account used to fund it\",\"roundUp\":\"Not a nearest-amount round-up: in the Landsbankinn app savings goals you can have a set amount from each debit or credit card transaction transferred to savings (alongside one-off, monthly and share-of-salary transfers)\",\"inactiveMonths\":24,\"dormancyWords\":\"Landsbankinn may close an account that has stood unused for 2 years or more, after sending notice; any balance is moved to another account of the customer, or to an account at the bank if they have none.\"},\"is-arion\":{\"source\":\"https://www.arionbanki.is/einstaklingar/sparnadur/sparnadarreikningar/voxtur-fastir-vextir/, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Vöxtur - fastir vextir (3, 6, 9 or 12 months, single deposit): rate and deposit are bound for the whole binding period; no early withdrawal stated.\",\"inactiveMonths\":24,\"dormancyWords\":\"If an account hasn't been used for 2 years or more Arion reserves the right to close it; the balance goes to another account of the customer or, if none, an interest-free holding account at the bank.\"},\"is-islandsbanki\":{\"source\":\"https://cdn.islandsbanki.is/image/upload/v1/documents/Fastvaxtareikningur.pdf, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Fastvaxtareikningur (1, 3, 6 or 12 months, single deposit, min ISK 100,000): principal can't be withdrawn and the account can't be changed or terminated during the binding; no fees charged.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\"],\"maturityWords\":\"when the binding ends the balance goes to the settlement account chosen at opening and the Fastvaxtareikningur is closed\",\"interestDuringTerm\":true,\"dormancyWords\":\"Íslandsbanki may close a zero-balance account that has stood unused over 4 year-ends without notice; no rule found for accounts holding a balance.\"},\"fr-bnp-paribas\":{\"source\":\"https://mabanque.bnpparibas/fr/epargner/comptes-livrets-epargne/depot-a-terme, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Dépôt à terme (DAT): early exit allowed only for the whole capital, 32-day notice; interest is recomputed for the exact days elapsed at the opening rate for the period actually run, reduced by the penalty in the Conditions Particulières (Moneyvox reports opening rate minus 0.5 point), floor 0%; no interest at all if closed within the first 30 days. No exit fees.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\"],\"maturityWords\":\"closed automatically at maturity; capital and interest paid to the current account (compte chèque) named at opening\",\"inactiveMonths\":12,\"dormantMonths\":120,\"dormancyWords\":\"Loi Eckert: current account inactive after 12 months (savings after 5 years); fees capped; funds transferred to the Caisse des Dépôts after 10 years without operation and the account closed.\"},\"fr-societe-generale\":{\"source\":\"https://static.sg.fr/bigfiles/pri/notices/SG_CAT-Taux-Fixe-7-24-mois_NIP.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"CAT Taux Fixe 7 à 24 mois: early repayment allowed with 32 calendar days' notice (nothing paid before), capital repaid in full, interest due reduced by 90% if under 1/3 of the term has run, 60% between 1/3 and 2/3, 30% beyond 2/3; plus flat break fees set in the lettre de blocage, capped at the interest actually paid. Withdrawal closes the CAT.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\"],\"maturityWords\":\"CAT Taux Fixe closes automatically at maturity; capital and interest paid in one go to the current account\",\"inactiveMonths\":12,\"dormantMonths\":120,\"dormancyWords\":\"Loi Eckert: 12 months with no client operation or contact makes the current account inactive; fee per 12-month period of inactivity; transfer to the Caisse des Dépôts after 10 years. SG does not charge the inactivity fee on savings accounts/livrets.\"},\"fr-lcl\":{\"source\":\"https://www.lcl.fr/livrets-epargne-logement/compte-a-terme-optilion-strategique-plus, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Compte à Terme Optilion Stratégique Plus: partial or full early withdrawal allowed with 31 days' notice (funds paid on day 32); the originally agreed rate is reduced on the amount withdrawn (size not published). Compte à Terme Fidélité: no interest if withdrawn in the first month. Compte à Terme Libre (1-month rolling): closing mid-month forfeits the current month's interest.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\"],\"maturityWords\":\"Optilion does not renew; capital and all interest are automatically transferred to the support (current) account at maturity (CAT Libre renews monthly)\",\"roundUp\":\"System'Épargne: free option; every card purchase is rounded up to the next euro and the difference is swept to an LCL savings account (own or a child's): end of month for deferred-debit cards, every two weeks for immediate-debit cards; cancelable free from the next day.\",\"inactiveMonths\":12,\"dormantMonths\":120,\"dormancyWords\":\"Loi Eckert: current account inactive after 12 months; annual fee within the available balance; transfer to the Caisse des Dépôts after 10 years.\"},\"fr-credit-agricole\":{\"source\":\"https://communication.ca-nord-est.fr/pdf/conditions-tarifaires/Plaquette_Prix_PART_2026.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Set by each caisse régionale and the contract: early exit generally possible; third-party sources say the rate is reduced by 0.50 to 1 point, and some contracts drop all interest. No bank-published figure found.\",\"inactiveMonths\":12,\"dormantMonths\":120,\"dormancyWords\":\"Loi Eckert: an account with no operation other than bank-initiated ones is inactive; fees taken yearly on each inactive account within 30 EUR and the credit balance; transfer to the Caisse des Dépôts after 10 years.\"},\"fr-la-banque-postale\":{\"source\":\"https://www.labanquepostale.fr/particulier/epargner/compte-a-terme.html, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Compte à terme taux fixe: withdrawal within the first month earns no interest; after one month a reduced rate (taux minoré) applies, pro rata on exact days, using the intermediate withdrawal rates predefined in the offer. Partial or total early withdrawal possible at any time.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"capital and interest paid at maturity; automatic renewal is an option chosen at subscription\",\"inactiveMonths\":12,\"dormantMonths\":120,\"dormancyWords\":\"Loi Eckert: 'Tenue de compte sans mouvement ou inactif' charged on accounts with no movement for over 12 months (not minors' accounts); total fees on inactive accounts capped at 30 EUR; transfer to the Caisse des Dépôts after 10 years.\"},\"de-deutsche-bank\":{\"source\":\"https://www.deutsche-bank.de/dam/deutschebank/de/shared/pdf/pk-sparen_geldanlage-festzinssparen-pib.pdf, 2026-09-26\",\"early\":false,\"penaltyWords\":\"FestzinsSparen (Spareinlage): no withdrawals during the fixed-rate period. Only in an emergency (unemployment, illness, insolvency, death) may the bank agree to early release, and then Vorschusszinsen are charged up to the end of the fixed-rate period, at least until the notice period expires, per the Bedingungen für Sparkonten / Aushang 'Zinssätze für Geldanlagen'.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"endNoticeDays\":90,\"maturityWords\":\"renews automatically for the same term at the then-current rate (currently for at most 1 year unless the customer asks otherwise); to be paid out the customer must give at least 3 months' notice before the end with a transfer order\",\"interestDuringTerm\":true,\"dormantMonths\":360,\"dormancyWords\":\"No statutory inactivity rule in Germany; the account keeps running. After 30 years without movement banks book the balance out, but the holder's claim can revive.\"},\"de-commerzbank\":{\"source\":\"https://www.commerzbank.de/privatkunden/sparen-anlegen/festgeld/, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Festgeld: no access at all during the term, not even to part of the balance.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"customer chooses at opening between automatic renewal on the same terms or payout; payout goes to the reference (Verrechnungs-) account\",\"dormantMonths\":360,\"dormancyWords\":\"No statutory inactivity rule in Germany; the account keeps running. After 30 years without movement banks book the balance out, but the holder's claim can revive.\"},\"de-postbank\":{\"source\":\"https://www.postbank.de/privatkunden/produkte/wertpapiere-sparen/sparen/zinssparen.html, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Zinssparen (Postbank's fixed-rate deposit, a Spareinlage): early access is not possible; withdrawals only at the end of the fixed-rate period after at least 3 months' notice. Sparkonto rule: if the bank exceptionally agrees to early repayment, Vorschusszinsen per Aushang 'Zinssätze für Geldanlagen' are deducted.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"endNoticeDays\":90,\"maturityWords\":\"keeps running for the same term at the then-current rate until the customer gives notice (at least 3 months before the end, with a transfer order)\",\"interestDuringTerm\":true,\"dormantMonths\":360,\"dormancyWords\":\"No statutory inactivity rule in Germany; the account keeps running. After 30 years without movement banks book the balance out, but the holder's claim can revive.\"},\"de-ing\":{\"source\":\"https://www.ing.de/sparen-anlegen/sparen/festgeld/kundenservice/, 2026-09-26\",\"early\":false,\"penaltyWords\":\"Festgeld: money cannot be accessed during the term; no early termination.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically for the same term at the then-current rate (capital plus interest); ING notifies 14 days before term end; choosing 'Auszahlen' in online banking stops renewal and capital plus interest go to the Verrechnungskonto (Girokonto or Extra-Konto) after term end\",\"roundUp\":\"Kleingeld Plus: every card payment is rounded up to the next full euro or next 5 euros (customer's choice); the rounding goes automatically to the Extra-Konto (Tagesgeld), available any time; can be changed or switched off at any time, starts the next bank working day.\",\"dormantMonths\":360,\"dormancyWords\":\"No statutory inactivity rule in Germany; the account keeps running. After 30 years without movement banks book the balance out, but the holder's claim can revive.\"},\"de-berliner-sparkasse\":{\"source\":\"https://www.berliner-sparkasse.de/content/dam/myif/berliner-sk/work/dokumente/pdf/preise-leistungen/preis-leistungsverzeichnis.pdf, 2026-09-26\",\"penaltyWords\":\"S-Festgeld: the product page offers no early exit. For Spareinlagen (Sparkassenbuch) the bank may exceptionally agree to early repayment and charges Vorschusszinsen of 1/4 of the account's interest rate until the notice period would have expired (max. 900 days).\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"endNoticeDays\":7,\"maturityWords\":\"S-Festgeld renews automatically for the same term at the then-current rate; tell the Kundenbetreuer at least 5 working days before term end to get the money instead\",\"interestDuringTerm\":true,\"dormantMonths\":360,\"dormancyWords\":\"No statutory inactivity rule in Germany; the account keeps running. After 30 years without movement banks book the balance out, but the holder's claim can revive.\"},\"es-santander\":{\"source\":\"https://roams.es/actualidad/finanzas/depositos-santander-rinden-mas-2-tae-15000-euros-nuevas-condiciones/, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Depósito Santander (6 and 12 months, min €15,000, for linked customers): early cancelation carries a 1% penalty (third-party press report; how the 1% is applied is not stated). Spanish rule (Banco de España): any early-cancelation fee or penalty must be in the contract and cannot exceed the gross interest accrued to the cancelation date, so capital is never lost.\",\"roundUp\":\"Hucha Santander (app and web, launched July 2021): rules include rounding each card purchase up to the next euro and moving the difference into the digital 'hucha', periodic contributions, saving a share of income, or saving when your football team scores; the money can be moved back to the account at any time.\",\"dormantMonths\":240,\"dormancyWords\":\"Spain (Ley 33/2003 art. 18, per Banco de España Portal del Cliente Bancario): an account with no holder activity for 20 years is legally 'abandoned' and the balance becomes property of the State; the bank must notify the holder by certified mail at least 3 months before the 20 years run out (not required if the notice would cost more than the balance).\"},\"es-bbva\":{\"source\":\"https://www.bbva.es/content/dam/public-web/bbvaes/documents/productos/depositos/deposito-combinado/precontractual-deposito-combinado-70-30.pdf (read via Wayback snapshot 2025-06-12), 2026-09-26\",\"early\":true,\"penaltyWords\":\"Depósito Combinado 30F/70D precontractual: early cancelation allowed. In the initial term, interest is settled at only 0.01% nominal a year on the canceled amount from opening to cancelation (the agreed rate is forfeited). In a renewal period, a penalty of 4.00% a year on the canceled amount for the days from cancelation to maturity, capped at the interest accrued. Third-party (Kelisto) reports BBVA's plain term deposit charges 2.75% a year on the canceled amount for the remaining period, capped at accrued interest.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\"],\"maturityWords\":\"paid out at maturity; no tacit renewal ('Renovación tácita ... NO'); capital and interest credited to the linked account\",\"roundUp\":\"'Regla del redondeo' in Programa tu Cuenta (BBVA app): each debit-card purchase that is not a whole euro is rounded up to the next euro and the difference moved to another BBVA account; an optional multiplier raises the amount.\",\"dormantMonths\":240,\"dormancyWords\":\"Spain (Ley 33/2003 art. 18, per Banco de España Portal del Cliente Bancario): an account with no holder activity for 20 years is legally 'abandoned' and the balance becomes property of the State; the bank must notify the holder by certified mail at least 3 months before the 20 years run out (not required if the notice would cost more than the balance).\"},\"es-caixabank\":{\"source\":\"https://www.caixabank.es/deployedfiles/particulares/Estaticos/pdf/Depositos/Precontrato-Bonificado-CAS.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Depósito Bonificado (1 year, min €5,000): total or partial early withdrawal allowed at any time. On a total early withdrawal no interest at all is paid (both the minimum and the conditional interest are forfeited); on a partial withdrawal the remainder keeps earning to maturity. No fee on top.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\"],\"maturityWords\":\"paid out at maturity to the linked sight account; 'No prorrogable' (not renewable)\",\"dormantMonths\":240,\"dormancyWords\":\"Spain (Ley 33/2003 art. 18, per Banco de España Portal del Cliente Bancario): an account with no holder activity for 20 years is legally 'abandoned' and the balance becomes property of the State; the bank must notify the holder by certified mail at least 3 months before the 20 years run out (not required if the notice would cost more than the balance).\"},\"es-sabadell\":{\"source\":\"https://www.bancsabadell.com/bsnacional/en/personal/savings/deposits/, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Depósito Online: early cancelation (total or partial) allowed with at least 35 days' notice, during which the amount is unavailable; penalty of 1% nominal a year on the amount canceled for the period from the early-cancelation date to the agreed maturity, capped at the gross interest accrued from the start. 14-day free withdrawal right after contracting.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically for the same amount and term at the rate then in force, unless non-renewal is requested any time before maturity (then capital and interest go to the linked account)\",\"roundUp\":\"Ahorro Sabadell (free with the Cuenta Online): savings rules that round up each purchase, save when it rains in a chosen city, or make regular/one-off transfers; savings can be withdrawn whenever you wish with no penalty.\",\"dormantMonths\":240,\"dormancyWords\":\"Spain (Ley 33/2003 art. 18, per Banco de España Portal del Cliente Bancario): an account with no holder activity for 20 years is legally 'abandoned' and the balance becomes property of the State; the bank must notify the holder by certified mail at least 3 months before the 20 years run out (not required if the notice would cost more than the balance).\"},\"es-bankinter\":{\"source\":\"https://www.bankinter.com/banca/en/investment-savings/savings/features-of-deposits, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Early cancelation (total or partial) allowed; Bankinter penalises by reducing the rate per the contract, never touching capital; interest already paid above the reduced rate is clawed back from the amount repaid. Current USD deposits: rate falls to 0.50% TIN on early cancelation (third-party). An older own-blog product (2013): the canceled amount earned 1.25% in year 1, 1.75% in year 2, 1.99% after.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"endNoticeDays\":3,\"maturityWords\":\"optional automatic renewal for the same term at the rate in force the business day before maturity; to stop (or add) renewal, notify at least 3 business days before maturity\",\"interestDuringTerm\":true,\"roundUp\":\"Modo Ahorro account (0% interest): card purchases rounded up to €1, €2 or any chosen amount (a €6.30 purchase sends €0.70, €1.70 or €4.70), debited from the linked current account once a day, the day after; withdrawals to the linked account any time, immediately.\",\"dormantMonths\":240,\"dormancyWords\":\"Spain (Ley 33/2003 art. 18, per Banco de España Portal del Cliente Bancario): an account with no holder activity for 20 years is legally 'abandoned' and the balance becomes property of the State; the bank must notify the holder by certified mail at least 3 months before the 20 years run out (not required if the notice would cost more than the balance).\"},\"jp-mufg\":{\"source\":\"https://www.bk.mufg.jp/regulation/teiki_super_jido.html, 2026-09-26\",\"early\":true,\"penaltyWords\":\"スーパー定期 (自動継続型): no termination before maturity unless the bank deems it unavoidable (やむを得ない). 期限前解約利率 by elapsed time: <6 months = ordinary savings rate on the cancelation day; 6m-1y = displayed 6-month rate at deposit ×70%; 1-2y = 1-year rate ×70%; 2-3y = 2-year rate ×70%; and so on to 9-10y = 9-year rate ×70% (each band uses the rate for the elapsed length, not the contracted one), never below the ordinary savings rate. Interim interest already paid in excess is deducted from principal.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically (自動継続) for the same term at the rate on the renewal date; to stop, tell the bank by the maturity date, and it is paid out at maturity to the designated account\",\"interestDuringTerm\":true,\"inactiveMonths\":24,\"dormantMonths\":120,\"dormancyWords\":\"未利用口座管理手数料: 普通預金 opened on/after 2021-07-01 with no deposit or withdrawal for 2 years (interest and the fee excluded) gets a notice; if still unused about 3 months later, ¥1,320/year is deducted. If the balance is below the fee, the whole balance is taken and the account closed. Exempt: accounts opened by 2021-06-30, holders with other assets or loans. Then: 10 years with no deposit/withdrawal activity: under the 休眠預金等活用法 (in force Jan 2018) the balance may be transferred to the Deposit Insurance Corporation (預金保険機構) as 休眠預金 after public notice; the holder can still reclaim it at the bank's counter (rule cited from Japan Post Bank's page stating the law, which applies to all Japanese banks).\"},\"jp-smbc\":{\"source\":\"https://www.smbc.co.jp/kojin/sougou/ippan/pdf/jido_teiki_super.pdf?version=231101, 2026-09-26\",\"early\":true,\"penaltyWords\":\"スーパー定期 (自動継続): no termination before maturity unless the bank deems it unavoidable. 期限前解約利率 depends on contract term and elapsed time. Terms 1 month to <3 years: <6m = ordinary savings rate; 6m-1y = contract rate ×50%; 1-3y = ×70%. 3-year term: <6m ordinary; 6m-1y ×40%; 1-1.5y ×50%; 1.5-2y ×60%; 2-2.5y ×70%; 2.5-3y ×90%. >3 to 4y term: ×10% (6m-1y), 20% (1-1.5y), 30% (1.5-2y), 40% (2-3y), 70% (3-4y). >4 to 5y term: ×10% (6m-1y), 20% (1-2y), 30% (2-3y), 50% (3-4y), 70% (4-5y). >5 to 7y term: as 5y, plus ×80% (5-6y) and ×90% (6-7y). Never below the ordinary savings rate; interim interest already paid is settled against it.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"renews automatically for the same term at the bank's rate on the renewal date; to stop, tell the bank by the maturity date and it is paid into the designated account at maturity\",\"interestDuringTerm\":true,\"inactiveMonths\":24,\"dormantMonths\":120,\"dormancyWords\":\"デジタル未利用手数料 (from 2024-04-01): 普通預金 with no deposit/transfer/withdrawal for 2+ years gets a letter; if still unused about 3 months later, ¥1,100/year is deducted, each later year without further notice. If the balance is below the fee, the balance is taken and the account closed. Exempt: opened by 2021-03-31, balance ≥ ¥10,000, digital channel set up (Web通帳 plus one-time password or SMBC Safety Pass), holder under 18 or 75+, other term/investment accounts at the branch, or a loan. Then: 10 years with no deposit/withdrawal activity: under the 休眠預金等活用法 (in force Jan 2018) the balance may be transferred to the Deposit Insurance Corporation (預金保険機構) as 休眠預金 after public notice; the holder can still reclaim it at the bank's counter (rule cited from Japan Post Bank's page stating the law, which applies to all Japanese banks).\"},\"jp-mizuho\":{\"source\":\"https://www.mizuhobank.co.jp/setsumeisho/pdf/teiki_super.pdf (read via Wayback snapshot; document dated 2021-01-17), 2026-09-26\",\"early\":true,\"penaltyWords\":\"みずほスーパー定期: 期日前解約利率 by contract term and elapsed time (can be 0%). Terms 1m to <3y: <6m = ordinary savings rate; 6m-1y = contract rate ×50%; 1-3y = ×70%. 3-year term: ×20% (6m-2y), ×40% (2-2.5y), ×60% (2.5-3y). >3-4y term: ×20% (6m-2y), ×40% (2-2.5y), ×60% (2.5-4y). >4-5y term: ×10% (6m-2y), ×20% (2-3y), ×40% (3-4y), ×70% (4-5y). Terms over 5 years: ordinary savings rate for the first year (rest of that table not captured). Interim interest paid in excess is repaid by the customer.\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\"],\"maturityWords\":\"automatic renewal (自動継続) available on fixed-term types if chosen at deposit; otherwise paid out; after maturity it earns the ordinary savings rate\",\"interestDuringTerm\":true,\"dormantMonths\":120,\"dormancyWords\":\"No unused-account fee found for Mizuho. Passbook accounts not updated (記帳) for the deposit term + 1 year as of each 31 January are switched automatically to みずほe-口座 (no paper passbook). Paper passbooks on accounts opened from 2021-01-18 cost ¥1,100 per book. Then: 10 years with no deposit/withdrawal activity: under the 休眠預金等活用法 (in force Jan 2018) the balance may be transferred to the Deposit Insurance Corporation (預金保険機構) as 休眠預金 after public notice; the holder can still reclaim it at the bank's counter (rule cited from Japan Post Bank's page stating the law, which applies to all Japanese banks).\"},\"jp-resona\":{\"source\":\"https://www.resonabank.co.jp/pdf/teiki_super.pdf (read via Wayback snapshot; document dated 2014-04-01), 2026-09-26\",\"early\":true,\"penaltyWords\":\"りそなスーパー定期: 期限前解約利率 by contract term and elapsed time. Terms 1m to <3y: <6m = ordinary savings rate; 6m-1y = contract rate ×50%; 1-3y = ×70%. 3-year term: ×40% (6m-1y), 50% (1-1.5y), 60% (1.5-2y), 70% (2-2.5y), 90% (2.5-3y). >3-4y term: ×10% (6m-1y), 20% (1-1.5y), 30% (1.5-2y), 40% (2-3y), 60% (3-4y). >4-5y term: ×10% (6m-1y), 20% (1-2y), 30% (2-3y), 50% (3-4y), 70% (4-5y). Interim interest paid in excess is deducted from principal.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"savings\"],\"maturityWords\":\"on fixed-term types, automatic renewal for the same term: 元加継続 (interest added to principal) or 利払継続 (interest paid out, principal renewed); after maturity earns the ordinary savings rate\",\"interestDuringTerm\":true,\"inactiveMonths\":24,\"dormantMonths\":120,\"dormancyWords\":\"未利用口座管理手数料: 普通預金 opened on/after 2004-04-01 with no deposit or withdrawal for 2+ years and a balance under ¥10,000 (among other conditions) gets a notice; using or closing the account within about 3 months avoids it, otherwise ¥1,320/year. Passbook accounts opened from 2023-01-16 may pay a ¥550/year passbook fee. Then: 10 years with no deposit/withdrawal activity: under the 休眠預金等活用法 (in force Jan 2018) the balance may be transferred to the Deposit Insurance Corporation (預金保険機構) as 休眠預金 after public notice; the holder can still reclaim it at the bank's counter (rule cited from Japan Post Bank's page stating the law, which applies to all Japanese banks).\"},\"jp-japan-post-bank\":{\"source\":\"https://www.jp-bank.japanpost.jp/setumeisho/pdf/teiki.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"定期貯金: withdrawal before the term ends pays the 預入期間内払戻利率, never below the 通常貯金 rate at deposit: <6m = 通常貯金 rate at deposit; 6m-1y = 6-month 定期 rate at deposit ×60%; 1-2y = 1-year rate ×60%; 2-3y = 2-year rate ×60%; and so on to 9-10y = 9-year rate ×60% (each band uses the rate for the elapsed length).\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"chosen at deposit: 継続預入 (principal + interest renewed for the same term), 再預入 (principal renewed, interest to 通常貯金) or 満期振替預入 (all to 通常貯金); 担保定期貯金 default to transfer into 通常貯金. Renewals are capped (e.g. 1-year: 9 times / 10 years); 10-year deposits cannot renew. After maturity it earns about the 通常貯金 rate.\",\"interestDuringTerm\":true,\"dormantMonths\":120,\"dormancyWords\":\"10+ years with no activity: after notice on the bank's website the balance may be transferred to the Deposit Insurance Corporation as 休眠貯金; ATM and ゆうちょダイレクト stop working, but it can still be withdrawn or reused at a counter. 定額/定期/積立郵便貯金 deposited before 2007-10-01: rights are extinguished if unclaimed 20 years 2 months after maturity (old Postal Savings Act).\"},\"kr-kb-kookmin\":{\"source\":\"https://obank.kbstar.com/quics?page=C016613&cc=b061496%3Ab061645&isNew=Y&prcode=DP01000938, 2026-09-26\",\"early\":true,\"penaltyWords\":\"KB Star 정기예금 (reduced-rate schedule, not days of interest): under 1 month 0.1%/yr; 1-3 months base rate x50% x elapsed/contract months (min 0.3%); 3-6 months x50% (min 0.5%); 6-8 months x60%; 8-10 months x70%; 10-11 months x80%; 11 months+ x90% (all min 0.5%). Base rate excludes preferential rates.\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\",\"paid_out\"],\"maturityWords\":\"customer must pick one at opening: auto-close (principal+interest paid to linked account), auto-renew principal only (interest paid out), or auto-renew principal+interest, at the rate posted on the renewal day; renewals up to 10 years in total. If left un-closed, 만기후이율 applies: within 1 month base x50%, 1-3 months base x30%, over 3 months 0.1%.\",\"interestDuringTerm\":true,\"roundUp\":\"KB스타뱅킹 '자투리 모으기' (added May 2020): on a scheduled day (daily/weekly/monthly) it withdraws the spare change below a chosen unit (1,000/5,000/10,000원) from the selected account and collects it.\",\"inactiveMonths\":12,\"dormantMonths\":60,\"dormancyWords\":\"After 1-3 years without transactions (balance under 10만원; 12/24/36 months for <1만/<5만/<10만원) the 입출금 account becomes a 거래중지계좌: deposits and withdrawals blocked until released at a branch with proof of purpose (or closed). After 5 years without a transaction (or 5 years past maturity for a term deposit) it becomes 휴면예금: the account contract ends and the balance may be transferred to 서민금융진흥원, from which the owner can reclaim it.\"},\"kr-shinhan\":{\"source\":\"https://img.shinhan.com/sbank2016/seol/20180220862400000030LC000030.PDF, 2026-09-26\",\"early\":true,\"penaltyWords\":\"쏠편한 정기예금 (reduced-rate schedule): under 1 month 0.10%/yr; from 1 month: base rate x (1 - deduction) x elapsed/contract months, min 0.10%. Deduction by elapsed period: 1-3 months 80% (i.e. 20% of base), 3-6 months 70% (30%), 6-9 months 30% (70%), 9-11 months 20% (80%), 11 months+ 10% (90%).\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\",\"paid_out\"],\"maturityWords\":\"optional auto-renewal (자동재예치, principal or principal+interest, at the base rate posted on renewal day, up to 10 years total) or automatic closure to the linked account; can also extend maturity once by up to 3 months at the original rate. Otherwise 만기후이자율: within 1 month 1/2 of the 일반정기예금 posted rate for that term (min 0.10%), 1-6 months 1/4 (min 0.10%), over 6 months 0.10%.\",\"interestDuringTerm\":true,\"inactiveMonths\":12,\"dormantMonths\":60,\"dormancyWords\":\"After 1-3 years without transactions (balance under 10만원; 12/24/36 months for <1만/<5만/<10만원) the 입출금 account becomes a 거래중지계좌: deposits and withdrawals blocked until released at a branch with proof of purpose (or closed). After 5 years without a transaction (or 5 years past maturity for a term deposit) it becomes 휴면예금: the account contract ends and the balance may be transferred to 서민금융진흥원, from which the owner can reclaim it.\"},\"kr-hana\":{\"source\":\"https://m.hanabank.com/cont/product/product02/product021/1448964_134045.jsp, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Hana 정기예금 (reduced-rate schedule): under 1 month 0.10%/yr; 1-3 months 0.15%; 3-6 months 0.20%; 6 months+ base rate x tier x elapsed days/contract days (min 0.20%), tier 60% for 6-9 months, 70% for 9-11 months, 90% for 11 months+. Rate truncated to 3 decimals.\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\"],\"endNoticeDays\":1,\"maturityWords\":\"하나의 정기예금: optional 만기자동재예치 (request by the day before maturity; principal or after-tax principal+interest; same term, at the rate posted on renewal day); otherwise it stays at the 만기후 rate: within 1 month 1/2 of the posted 일반정기예금 월이자지급식 base rate, over 1 month 1/4.\",\"interestDuringTerm\":true,\"inactiveMonths\":12,\"dormantMonths\":60,\"dormancyWords\":\"After 1-3 years without transactions (balance under 10만원; 12/24/36 months for <1만/<5만/<10만원) the 입출금 account becomes a 거래중지계좌: deposits and withdrawals blocked until released at a branch with proof of purpose (or closed). After 5 years without a transaction (or 5 years past maturity for a term deposit) it becomes 휴면예금: the account contract ends and the balance may be transferred to 서민금융진흥원, from which the owner can reclaim it.\"},\"kr-nh\":{\"source\":\"https://img.nonghyup.com/file/ebank/product/guide/10001160_pi.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"NH올원e예금 (큰만족실세예금 early rates, reduced-rate schedule): under 3 months 0.1%/yr; 3-6 months base x50% x elapsed/contract months; 6-9 months x60%; 9-11 months x70%; 11 months+ x80%; minimum 0.1%, truncated to 3 decimals, part-months dropped.\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"paid_out\"],\"maturityWords\":\"no auto-renewal (재예치 불가); optional automatic closure at maturity (자동 만기해지 서비스). Left un-closed it earns 만기후이자율: within 3 months 50% of the 큰만족실세예금 base rate for the term, 3-6 months 20%, over 6 months 10%.\",\"interestDuringTerm\":true,\"inactiveMonths\":12,\"dormantMonths\":60,\"dormancyWords\":\"After 1-3 years without transactions (balance under 10만원; 12/24/36 months for <1만/<5만/<10만원) the 입출금 account becomes a 거래중지계좌: deposits and withdrawals blocked until released at a branch with proof of purpose (or closed). After 5 years without a transaction (or 5 years past maturity for a term deposit) it becomes 휴면예금: the account contract ends and the balance may be transferred to 서민금융진흥원, from which the owner can reclaim it.\"},\"kr-kakaobank\":{\"source\":\"https://www.kakaobank.com/products/deposit, 2026-09-26\",\"early\":true,\"penaltyWords\":\"카카오뱅크 정기예금 (reduced-rate schedule): base rate at opening x N% x elapsed days/contract days, N = 10% under 1 month (min 0.10%), 30% for 1-3 months (min 0.30%), 50% for 3-6 months, 70% for 6-9 months, 80% for 9-11 months, 90% for 11 months+ (min 0.50% from 3 months).\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\",\"paid_out\"],\"maturityWords\":\"customer chooses auto-close, auto-renew (after-tax principal+interest re-deposited for the same term at the posted rate, up to 5 times; not for 비과세종합저축 or accounts with legal holds), or manual. Un-closed deposits earn 만기후금리: within 1 month base x50%, 1-3 months base x30%, over 3 months 0.20%.\",\"roundUp\":\"저금통: linked to a KakaoBank 입출금 account; '동전 모으기' sweeps the under-1,000원 remainder (1-999원) of the account into the 저금통 on weekdays (Mon-Fri); '자동 모으기' saves an algorithm-chosen 1,000-10,000원 each Saturday; balance capped at 10만원; can be emptied to the linked account at any time.\",\"inactiveMonths\":12,\"dormantMonths\":60,\"dormancyWords\":\"After 1-3 years without transactions (balance under 10만원; 12/24/36 months for <1만/<5만/<10만원) the 입출금 account becomes a 거래중지계좌: deposits and withdrawals blocked until released at a branch with proof of purpose (or closed). After 5 years without a transaction (or 5 years past maturity for a term deposit) it becomes 휴면예금: the account contract ends and the balance may be transferred to 서민금융진흥원, from which the owner can reclaim it.\"},\"au-commbank\":{\"source\":\"https://www.commbank.com.au/personal/apply-online/download-printed-forms/TermDeposit_ADB202.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"31 days' notice, then a prepayment interest adjustment by share of term elapsed: the rate is cut by 90% (0-<20% elapsed), 80% (20-<40%), 60% (40-<60%), 40% (60-<80%), 20% (80-<100%) of the agreed rate; plus a $30 prepayment administration fee. Total paid is never below the principal (excluding the $30 fee).\",\"atEnd\":\"savings\",\"endChoices\":[\"savings\",\"renews\",\"paid_out\"],\"maturityWords\":\"Renewal Notice sent before maturity; if you give no instructions before maturity the money goes to the at-call holding facility (lower variable rate, interest paid every 7 days), not auto-renewed. 7-day terms go to the holding facility automatically.\",\"graceDays\":7,\"interestDuringTerm\":true,\"inactiveMonths\":3,\"dormantMonths\":84,\"dormancyWords\":\"CBA may close an account with a balance under $10 that has not been used for at least 3 months. After 7 years with no deposit or withdrawal (and no request to keep it active), balances over a specified amount go to the Commonwealth unclaimed money fund (reclaimable, may earn interest); smaller balances earn no interest. Debit card/Keycard may be canceled if unused for 6 months. Passbook Savings/Savings Investment monthly fee is not charged while the account is inactive.\",\"stopsInterest\":true},\"au-westpac\":{\"source\":\"https://www.westpac.com.au/content/dam/public/wbc/documents/pdf/pb/TermDeposits-tandc.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"31 days' notice (unless hardship); interest rate reduced by share of term elapsed: no interest if closed <7 days into the term; otherwise the rate is reduced by 90% (<20% elapsed), 80% (20-39.99%), 60% (40-59.99%), 40% (60-79.99%), 20% (80-99.99%) of the account's rate. No reduction on death or hardship. Interim interest already paid may be recovered.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"savings\",\"paid_out\"],\"maturityWords\":\"Renews automatically under the same conditions as the previous term (at the rate in the Maturity Advice) unless other instructions; a special rate may roll to a lower rate. 6 Business day Variation Period from maturity to change once; On Demand rate applies between maturity and renewal/closure.\",\"graceDays\":6,\"interestDuringTerm\":true,\"inactiveMonths\":6,\"dormantMonths\":84,\"dormancyWords\":\"An account is inactive if there are no deposits/withdrawals for a continuous 6 months AND the balance is nil or in debit; Westpac may then close it without notice. After 7 years with no deposit or withdrawal Westpac may close the account and transfer prescribed money to the government as unclaimed money (usually with notice); Bump Savings is exempt until the holder turns 18.\"},\"au-nab\":{\"source\":\"https://www.nab.com.au/content/dam/nab/documents/terms-and-conditions/investment/term-deposit-terms-and-conditions-260430.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"31 calendar days' notice (may be waived for hardship); reduction of interest based on the share of the term REMAINING: you keep 80% of interest earned (0-<20% remaining), 60% (20-<40%), 40% (40-<60%), 20% (60-<80%), 10% (80-<100%). Interest already paid is taken into account and deducted from the payout; you never get less than the original principal.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"NAB may (not must) reinvest for the same term at the rate on the maturity day if no instructions; deposits under $5,000 may be repaid instead. You can change term/amount/frequency up to 7 calendar days after the new term starts.\",\"graceDays\":7,\"interestDuringTerm\":true,\"dormantMonths\":84,\"dormancyWords\":\"NAB may close a zero-balance account without prior notice and may cancel a debit card not used for at least two years; on closure a credit balance may have to be transferred to the Government as unclaimed money (the Commonwealth rule is 7 years without a deposit or withdrawal, per ASIC).\"},\"au-anz\":{\"source\":\"https://www.anz.com.au/content/dam/anzcomau/documents/pdf/saving-transaction-products-tcs.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"ANZ Advance Notice Term Deposit: 31 days' notice (shorter possible in hardship). Any early withdrawal (except after an account holder's death): $30 administration fee plus an interest reduction on the withdrawn amount by share of the original term elapsed: 90% (0-<20%), 80% (20-<40%), 60% (40-<60%), 40% (60-<80%), 20% (80-<100%).\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"Reinvests automatically into a new ANZ term deposit with the same term and interest frequency if no instructions and the balance is $5,000 or more (ANZ may stop reinvesting after 3 years without instructions); under $5,000 may be paid out. 7 days after maturity to change reinvestment instructions without it counting as an early withdrawal.\",\"graceDays\":7,\"interestDuringTerm\":true,\"roundUp\":\"ANZ Plus Round Ups (ANZ Plus app accounts only): eligible ANZ Plus Visa Debit card and digital wallet purchases, not direct debits, BPAY, Pay Anyone or ATM withdrawals, are rounded up to the nearest $1, $2, $5 or $10 and the difference is moved to an ANZ Plus savings account/Savings Jar/goal or an ANZ Plus home loan. For example, a $13 purchase rounded to $5 moves $2. It can be switched on or off at any time.\",\"inactiveMonths\":84,\"dormantMonths\":84,\"dormancyWords\":\"If you haven't operated the account for 7 years and the balance is above $0 and under $500, ANZ may close it. If the balance is over $500 after 7 years without operation, ANZ may be required by law to send it to the Government as unclaimed money (reclaimable at any time).\"},\"nz-anz\":{\"source\":\"https://www.anz.co.nz/content/dam/anzconz/documents/personal/accounts/Term-Deposit-Info-Brochure.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Early withdrawal only with 31 days' notice or on hardship, and ANZ doesn't have to agree outside the 7-day cooling-off. If allowed, the interest rate on the withdrawn amount is cut by the early withdrawal rate reduction, currently 1% p.a. (the return can't go below 0%). Worked as amount withdrawn x reduction rate / 365 x days invested. No break fee.\",\"atEnd\":\"renews\",\"endChoices\":[\"renews\",\"paid_out\"],\"maturityWords\":\"Reinvests automatically for a similar term at the rate then applying unless told otherwise; a new 7-calendar-day cooling-off period starts on reinvestment (cancel or change the term or amount; canceling forfeits interest for the period).\",\"graceDays\":7,\"interestDuringTerm\":true,\"freeWithdrawals\":1,\"withdrawalFee\":500,\"inactiveMonths\":12,\"dormantMonths\":60,\"dormancyWords\":\"ANZ can close an account with a $0 balance that has been inactive for at least one year. Under the Unclaimed Money Act 1971, if none of the owner's accounts has been transacted on for 5 years, there's been no other contact and ANZ can't reach the owner, balances over $100 go to Inland Revenue (reclaimable); $100 or less is donated to charity. Term deposits count from 5 years after the end of the first term.\"},\"nz-asb\":{\"source\":\"https://www.asb.co.nz/content/dam/asb/documents/term-investments/2023/asb-term-deposit-early-withdrawal-information-april-2023.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"ASB agrees only on 31 days' prior notice or an approved 'exceptional circumstance' (money is then released the same day). A request in the first 5 calendar days needs neither. The break rate on the withdrawn amount is the rate that applied when the deposit was opened or reinvested, for the term actually completed, less 2% p.a., subject to a minimum break rate (0.05% p.a. in ASB's example). Interest already paid above that is deducted from principal.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"Reinvested or paid out per your instructions. Deposits of 30 days or longer have a 5-calendar-day grace period (counting the day it is opened or reinvested) to change instructions or close; deposits under 30 days have 1 day.\",\"graceDays\":5,\"interestDuringTerm\":true,\"freeWithdrawals\":1,\"roundUp\":\"Save the Change: rounds up selected EFTPOS and ASB Visa Debit card transactions and electronic payments (including direct debits and automatic payments) from an ASB everyday account to the nearest $1, $2, $5 or $10. It totals the day's round-ups and moves them to the chosen ASB savings account(s) in one overnight transfer. Not available on credit cards, and it keeps running into an arranged overdraft.\",\"dormantMonths\":60,\"dormancyWords\":\"Under the Unclaimed Money Act, if 5 or more years pass since you last transacted and ASB has had no other contact with you, ASB tries to reach you. Without new activity by the deadline the accounts are closed and the money transferred to Inland Revenue.\"},\"nz-bnz\":{\"source\":\"https://www.bnz.co.nz/support/investments/term-deposits/making-an-early-term-deposit-withdrawal, 2026-09-26\",\"early\":true,\"penaltyWords\":\"From 7 days after opening, early withdrawal needs 31 days' notice or approved financial hardship (paid next business day). BNZ keeps a share of the interest by share of term REMAINING: 80% of the rate (0-<20% remaining), 60% (20-<40%), 40% (40-<60%), 20% (60-<80%), 10% (80-<100%). The reduction can leave no interest, and interest already paid can be recovered.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"endNoticeDays\":1,\"maturityWords\":\"Handled per the instruction given at setup: pay to a nominated account, reinvest for a further term, or repay another agreed way. It can be changed as often as you like up to the business day before maturity. No post-maturity grace period was found.\",\"interestDuringTerm\":true,\"freeWithdrawals\":1,\"withdrawalFee\":300,\"dormantMonths\":60,\"dormancyWords\":\"If an account hasn't been touched for 5 years, the owner hasn't dealt with BNZ otherwise and can't be reached, BNZ closes it and pays the money to Inland Revenue (Unclaimed Money Act 1971). Balances of $100 or less go to charity. Term deposits count from 5 years after the first term ends. BNZ warns by letter, email, SMS or phone first.\"},\"nz-westpac\":{\"source\":\"https://assets.dam.westpac.co.nz/is/content/wnzl/dist/kiwisaver-investments-and-managed-funds/term-investments/westpac-term-deposit/Term-Deposit_Term-Sheet_brochure.pdf, 2026-09-26\",\"early\":true,\"penaltyWords\":\"After the 7-working-day cooling-off, Westpac may agree to early withdrawal only on 32 days' notice or for hardship, and doesn't have to agree even with notice. The rate on the withdrawn amount becomes the lower of (A) the agreed rate less 2%, or (B) the rate on offer at opening for the term matching the time actually invested, less 2% (never below 0%). No reduction if you withdraw at most 20% once from a 1-year+ term, keep the minimum balance and make no other early withdrawal. Hardship is calculated differently. No fees.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"You choose at opening to have the maturity amount paid to an NZ bank account or reinvested. Instructions can be given within 15 working days before the end of the term. Reinvesting starts a new 7-working-day cooling-off period.\",\"graceDays\":7,\"interestDuringTerm\":true,\"dormantMonths\":60,\"dormancyWords\":\"Under the Unclaimed Money Act, Westpac pays the funds to Inland Revenue where the account hasn't been touched for 5 years (term deposits: 5+ years after the first term ended), the owner hasn't dealt with Westpac otherwise and can't be reached. A warning letter is sent if a valid address is held.\"},\"nz-kiwibank\":{\"source\":\"https://www.kiwibank.co.nz/personal-banking/investments/rates-and-charges/breaking-term-deposit/, 2026-09-26\",\"early\":true,\"penaltyWords\":\"Breaking needs an application and Kiwibank's agreement. In the first 30 days you get the principal back with no interest. After 30 days, an early termination charge cuts the rate on the withdrawn amount to the LOWER of: the advertised rate on the approval day, or on the opening day, for the term nearest the time actually invested, less 2 percentage points (never below 0%). No notice period is stated.\",\"atEnd\":\"paid_out\",\"endChoices\":[\"paid_out\",\"renews\"],\"maturityWords\":\"Per your maturity instructions: either reinvest the principal (and interest) automatically for the same term at the rate on the maturity day, or pay it all to a chosen account. After a reinvestment you have up to 5 business days to make changes.\",\"graceDays\":5,\"interestDuringTerm\":true,\"dormantMonths\":60,\"dormancyWords\":\"No Kiwibank page could be read. The Unclaimed Money Act 1971 applies to all NZ banks: per the ANZ, BNZ, ASB and Westpac NZ pages, after 5 years with no transactions and no contact the money goes to Inland Revenue, and balances of $100 or less may go to charity.\"}}");

/** By country, ISO alpha-2 upper case. */
export const UNCLAIMED: Readonly<Record<string, CountryUnclaimed>> = JSON.parse("{\"US\":{\"source\":\"https://www.cullenllp.com/blog/electronic-contact-from-a-customer-is-now-sufficient-to-avoid-reporting-deposit-accounts-as-abandoned-property-in-new-york/, 2026-09-26\",\"years\":3,\"to\":\"the state's unclaimed-property office (New York: 3 years of no activity or contact, reported to the State Comptroller)\",\"claimBack\":\"yes, from the state office; New York: no fee and no time limit\"},\"CA\":{\"source\":\"https://www.canada.ca/en/financial-consumer-agency/services/banking/unclaimed-balances.html, 2026-09-26\",\"years\":10,\"to\":\"the Bank of Canada (Unclaimed Properties Office), for federally regulated banks\",\"claimBack\":\"yes, claim from the Bank of Canada; it holds balances under $1,000 for 30 years and $1,000 or more for 100 years\",\"coolingOffDays\":14},\"MX\":{\"source\":\"https://www.gob.mx/condusef/prensa/sabias-que-si-tu-cuenta-bancaria-no-registra-movimiento-tus-recursos-pueden-pasar-a-la-beneficencia-publica, 2026-09-26\",\"years\":6,\"to\":\"after 3 years without movement the balance goes to the bank's 'cuenta global' (90 days' written notice first); after 3 more years there, amounts up to 300 days of minimum wage prescribe to the Beneficencia Pública\",\"claimBack\":\"yes while in the cuenta global (contract and official ID at the bank); once prescribed to the Beneficencia, no\",\"coolingOffDays\":10},\"GB\":{\"source\":\"https://www.reclaimfund.co.uk/the-schemes/the-main-scheme/, 2026-09-26\",\"years\":15,\"to\":\"the Reclaim Fund (UK Dormant Assets Scheme), if the bank chooses to transfer\",\"claimBack\":\"yes, at any time, through the original bank or building society\",\"coolingOffDays\":14},\"IE\":{\"source\":\"https://www.citizensinformation.ie/en/money-and-tax/personal-finance/banking/dormant-bank-accounts-in-ireland/, 2026-09-26\",\"years\":15,\"to\":\"the Dormant Accounts Fund (account becomes dormant on 30 September after 15 years with no transaction; funds move after 31 March following)\",\"claimBack\":\"yes, always, including interest, via a Dormant Account Claim Form sent to the institution\",\"coolingOffDays\":14},\"IS\":{\"source\":\"https://www.althingi.is/lagas/nuna/2007150.html, 2026-09-26\",\"years\":20,\"to\":\"no state unclaimed-money scheme found; the deposit claim itself prescribes 20 years after the last deposit or withdrawal, and only if the bank has verifiably warned the holder\",\"claimBack\":\"yes until prescription; after prescription the claim is extinguished\",\"coolingOffDays\":14},\"FR\":{\"source\":\"https://www.caissedesdepots.fr/rechercher-des-assurances-vie-et-des-comptes-bancaires-inactifs, 2026-09-26\",\"years\":10,\"to\":\"the Caisse des Dépôts (searchable on Ciclade) after 10 years of inactivity (3 years after the holder's death); the CDC holds it 20 years (27 after death), then it passes to the State\",\"claimBack\":\"yes, from the Caisse des Dépôts via Ciclade, until the State acquires it\",\"coolingOffDays\":14},\"DE\":{\"source\":\"https://uk.news.yahoo.com/owns-billions-germanys-forgotten-accounts-084300580.html, 2026-09-26\",\"to\":\"none: Germany has no legal framework or official definition for dormant accounts; the balance stays with the bank until claimed; the state only takes it as statutory heir\",\"claimBack\":\"yes, no time limit (per Deutsche Welle)\",\"coolingOffDays\":14},\"ES\":{\"source\":\"https://www.boe.es/buscar/act.php?id=BOE-A-2003-20254, 2026-09-26\",\"years\":20,\"to\":\"the State (Administración General del Estado) under art. 18 Ley 33/2003, after 20 years with no act by the holder exercising ownership; per the amended art. 18.2 the money funds education and accessibility programs for people with disabilities\",\"claimBack\":\"not established: the law vests the balance in the State; no reclaim route was found\",\"coolingOffDays\":14},\"JP\":{\"source\":\"https://www.fsa.go.jp/policy/kyuminyokin/kyuminyokin.html, 2026-09-26\",\"years\":10,\"to\":\"the Deposit Insurance Corporation of Japan (預金保険機構), for deposits with no transactions for 10 years or more (since 1 Jan 2009)\",\"claimBack\":\"yes, with no time limit ('期限はありません。いつでも引き出すことができます'), at the original bank\"},\"KR\":{\"source\":\"https://www.kinfa.or.kr/cyber/appInfo/sleepMoneyInf.do, 2026-09-26\",\"years\":5,\"to\":\"the Korea Inclusive Finance Agency (서민금융진흥원) once the claim prescribes 5 years after the last transaction (e.g. last interest payment)\",\"claimBack\":\"yes, the original owner can claim; no deadline stated; online up to KRW 20 million per item, paid the same day\",\"coolingOffDays\":14},\"AU\":{\"source\":\"https://www.asic.gov.au/regulatory-resources/financial-services/unclaimed-money/changes-to-the-commonwealth-unclaimed-money-laws, 2026-09-26\",\"years\":7,\"to\":\"ASIC (Commonwealth unclaimed money), for bank accounts with no deposit or withdrawal for 7 years and a balance of $500 or more\",\"claimBack\":\"yes, via Moneysmart; free\"},\"NZ\":{\"source\":\"https://www.ird.govt.nz/unclaimed-money/claiming-unclaimed-money, 2026-09-26\",\"years\":5,\"to\":\"Inland Revenue (unclaimed money), after 5 years with no contact (in limited cases less)\",\"claimBack\":\"yes, within 20 years: IRD holds unclaimed money for 20 years, after which no further claims can be made\"}}");
